<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {Search,Download,ArrowUpRight,MapPin,Users,Rows3} from 'lucide-vue-next'
import {data,latin,money,num,sum,organization,aggregateFinance,saveCSV,type FinanceRow} from './data'
import RegionMap from './RegionMap.vue'
const props=defineProps<{initial?:string;year:number;region:string;agency:string;selectedMonths:number[]}>()
const emit=defineEmits<{region:[string];open:[FinanceRow];family:[string];cut:[string]}>()
const cut=ref(props.initial??'measures'),query=ref(''),type=ref(''),direction=ref(''),cohort=ref(''),metric=ref('amount'),district=ref(''),sex=ref(''),age=ref(''),benefit=ref('')
const lines=computed(()=>data.finance.filter(l=>(!props.agency||l.o===props.agency)&&(!query.value||latin(l.n).toLowerCase().includes(latin(query.value).toLowerCase()))&&(!type.value||l.t===type.value)&&(!direction.value||l.d===direction.value)&&(!cohort.value||l.c===cohort.value)))
const rows=computed(()=>lines.value.map(l=>aggregateFinance(l,props.year,props.region,props.selectedMonths)).filter(r=>r.total||r.count).sort((a,b)=>metric.value==='amount'?b.total-a.total:b.count-a.count))
const regional=computed(()=>data.regions.map((name,i)=>({name,i,total:sum(lines.value.map(l=>aggregateFinance(l,props.year,String(i),props.selectedMonths).total))})))
const peopleRows=computed(()=>data.cube.filter(([d,t,s,a])=>(props.region===''||data.regionMap[data.districts[d]![0]]===+props.region)&&(district.value===''||d===+district.value)&&(benefit.value===''||t===+benefit.value)&&(sex.value===''||s===+sex.value)&&(age.value===''||a===+age.value)))
const filteredPeople=computed(()=>data.cubePeople.filter(([d,s,a])=>(props.region===''||data.regionMap[data.districts[d]![0]]===+props.region)&&(district.value===''||d===+district.value)&&(sex.value===''||s===+sex.value)&&(age.value===''||a===+age.value)))
const peopleCount=computed(()=>{if(props.selectedMonths.length===12)return benefit.value!==''?sum(peopleRows.value.map(r=>r[4])):sum(filteredPeople.value.map(r=>r[3]));return sum(props.selectedMonths.map(i=>benefit.value!==''?sum(peopleRows.value.map(r=>r[5][i]??0)):sum(filteredPeople.value.map(r=>r[4][i]??0))))/Math.max(1,props.selectedMonths.length)})
watch(()=>props.region,()=>district.value='')
const peopleSum=computed(()=>sum(peopleRows.value.flatMap(r=>props.selectedMonths.map(i=>r[6][i]??0))))
const districts=computed(()=>data.districts.map(([r,name],i)=>({i,r,name})).filter(x=>props.region===''||data.regionMap[x.r]===+props.region))
const districtRows=computed(()=>districts.value.map(d=>({...d,amount:sum(peopleRows.value.filter(r=>r[0]===d.i).flatMap(r=>props.selectedMonths.map(i=>r[6][i]??0)))})).filter(x=>x.amount).sort((a,b)=>b.amount-a.amount))
const peopleFamilies=computed(()=>data.families.filter(f=>(props.region===''||f.region===+props.region)&&f.members.some(m=>(sex.value===''||m.sex===(sex.value==='0'?'э':'а'))&&(age.value===''||(m.age!==null&&(m.age<18?0:m.age<30?1:m.age<60?2:3)===+age.value)))).slice(0,60))
function download(){saveCSV('Korsatilgan_choralar.csv',[['Chora','Idora','Tanlangan summa mlrd','Oluvchilar','Hisob turi'],...rows.value.map(r=>[latin(r.line.n),organization(r.line.o),r.total,r.line.cnt===null?'Noma’lum':r.count,r.line.k==='m'?'O‘rtacha oylik oluvchi':'Oluvchilar'])])}
</script>
<template><div><div class="section-heading"><div><h2>Ko‘rsatilgan choralar tahlili</h2><p>Chora → hudud → tuman → fuqaro kesimi</p></div><button class="np-button" @click="download"><Download :size="14"/>Eksport</button></div><div class="np-toolbar finance-cut"><div class="np-segment"><button :class="{active:cut==='measures'}" @click="cut='measures';emit('cut','measures')"><Rows3 :size="14"/>Choralar</button><button :class="{active:cut==='regions'}" @click="cut='regions';emit('cut','regions')"><MapPin :size="14"/>Hududlar</button><button :class="{active:cut==='people'}" @click="cut='people';emit('cut','people')"><Users :size="14"/>Fuqarolar kesimi</button></div></div><template v-if="cut!=='people'"><div class="np-card"><div class="np-toolbar"><label class="np-search"><Search :size="15"/><input v-model="query" placeholder="Chora nomini qidirish" aria-label="Ko‘rsatilgan chora qidiruvi"/></label><select v-model="type" aria-label="Ko‘mak turi"><option value="">Barcha turlar</option><option v-for="(name,key) in data.labels.types" :key="key" :value="key">{{ latin(name) }}</option></select><select v-model="direction" aria-label="Ko‘mak yo‘nalishi"><option value="">Barcha yo‘nalishlar</option><option v-for="(name,key) in data.labels.directions" :key="key" :value="key">{{ latin(name) }}</option></select><select v-model="cohort" aria-label="Ko‘mak toifasi"><option value="">Barcha toifalar</option><option v-for="(name,key) in data.labels.cohorts" :key="key" :value="key">{{ latin(name) }}</option></select></div><div v-if="cut==='regions'" class="finance-region-grid"><RegionMap :values="regional.map(r=>r.total*1e9)" :selected="region" @select="emit('region',$event)"/><div class="region-ranking"><button v-for="r in [...regional].sort((a,b)=>b.total-a.total)" :key="r.i" :class="{selected:region===String(r.i)}" @click="emit('region',String(r.i))"><span>{{ latin(r.name) }}</span><b>{{ money(r.total*1e9) }}</b><i :style="{width:r.total/Math.max(...regional.map(x=>x.total),1)*100+'%'}"/></button></div></div><div class="np-toolbar"><p>{{ rows.length }} ta chora · {{ money(sum(rows.map(x=>x.total))*1e9) }} so‘m</p><div class="np-segment"><button :class="{active:metric==='amount'}" @click="metric='amount'">Summa</button><button :class="{active:metric==='count'}" @click="metric='count'">Oluvchilar</button></div></div><div class="np-table-wrap"><table class="np-table"><thead><tr><th>Chora</th><th>Idora</th><th>Ko‘rsatilgan ko‘mak</th><th>Oluvchilar</th><th>Vedomost ijrosi</th><th></th></tr></thead><tbody><tr v-for="row in rows" :key="row.line.id"><td><button class="text-button" @click="emit('open',row)">{{ latin(row.line.n) }}</button><small>{{ latin(data.labels.types[row.line.t]) }} · {{ latin(data.labels.directions[row.line.d]) }}</small></td><td>{{ organization(row.line.o) }}</td><td><b>{{ money(row.total*1e9) }}</b><small>so‘m</small></td><td>{{ row.line.cnt===null?'Ma’lumot yo‘q':num(row.count) }}<small>{{ row.line.k==='m'?'O‘rtacha oylik oluvchi':'Oluvchilar' }}</small></td><td><span v-if="row.plan" class="np-tag" :class="row.total/row.plan<.9?'amber':'green'">{{ num(row.total/row.plan*100,1) }}%</span><span v-else>—</span></td><td><button class="icon-button" :aria-label="latin(row.line.n)+' tafsiloti'" @click="emit('open',row)"><ArrowUpRight :size="16"/></button></td></tr><tr v-if="!rows.length"><td colspan="6" class="np-empty">Tanlov bo‘yicha summa mavjud emas. Bu idoraning barcha xizmatlari nol degani emas.</td></tr></tbody></table></div><p class="np-note">Oluvchilar chora kesimida hisoblanadi. Turli choralar bo‘yicha sonlar noyob fuqarolar jami sifatida qo‘shilmaydi. Hudud kesimi Agentlikning manbada mavjud choralarini qamraydi.</p></div></template><template v-else><div class="np-notice blue">Nafaqa bazasi · 2025-yil. Fuqarolar kesimi umumiy moliyaviy jadvaldan alohida. Barcha idoralar bo‘yicha noyob qamrov sifatida talqin qilinmaydi.</div><section class="np-card"><div class="np-toolbar"><select v-model="district" aria-label="Fuqaro tumani"><option value="">Barcha tumanlar</option><option v-for="d in districts" :key="d.i" :value="String(d.i)">{{ latin(d.name) }}</option></select><select v-model="benefit" aria-label="Nafaqa turi"><option value="">Barcha nafaqa turlari</option><option v-for="(name,i) in data.benefitTypes" :key="i" :value="String(i)">{{ latin(name) }}</option></select><select v-model="sex" aria-label="Jins"><option value="">Barcha jinslar</option><option value="0">Erkak</option><option value="1">Ayol</option></select><select v-model="age" aria-label="Yosh guruhi"><option value="">Barcha yoshlar</option><option v-for="(name,i) in ['18 yoshgacha','18–29 yosh','30–59 yosh','60 va undan katta']" :key="i" :value="String(i)">{{ name }}</option></select></div><div class="people-metrics"><div><span>{{ selectedMonths.length===12?'Kesimdagi yillik hisoblar':'O‘rtacha oylik oluvchilar' }}</span><strong>{{ num(peopleCount) }}</strong><small>Hududlararo takrorlar bo‘lishi mumkin</small></div><div><span>Tanlangan oylarda to‘lov</span><strong>{{ money(peopleSum*1e6) }}</strong><small>so‘m</small></div><div><span>Tumanlar</span><strong>{{ districtRows.length }}</strong><small>To‘lov ma’lumoti mavjud</small></div></div><div class="finance-region-grid"><div><h3>Tumanlar bo‘yicha to‘lov</h3><div class="district-scroll"><button v-for="d in districtRows" :key="d.i" class="district-row" @click="district=district===String(d.i)?'':String(d.i)"><span>{{ latin(d.name) }}</span><b>{{ money(d.amount*1e6) }}</b></button></div></div><div><h3>Oila pasportlari · namuna</h3><p class="np-note">F.I.Sh. shartli. Tuman bo‘yicha shaxs bog‘lanishi namunada berilmagan.</p><div class="district-scroll"><button v-for="f in peopleFamilies" :key="f.id" class="district-row" @click="emit('family',f.id)"><span>{{ latin(f.members[0]?.name) }}<small>{{ latin(data.regions[f.region]) }} · {{ f.members.length }} a’zo</small></span><ArrowUpRight :size="15"/></button></div></div></div></section></template></div></template>
<style scoped>.finance-cut{margin-bottom:20px}.finance-region-grid{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin:20px 0}.region-ranking{display:grid;gap:5px}.region-ranking button{display:flex;justify-content:space-between;position:relative;gap:15px;font-size:11px;text-align:left;padding:8px 0;color:var(--muted-foreground)}.region-ranking button b{color:#496d9e;white-space:nowrap}.region-ranking button i{position:absolute;bottom:0;left:0;height:2px;background:#abc0f0;transition:width .5s}.region-ranking button.selected{background:#edf3ff}.np-table td:first-child{min-width:270px}.people-metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin:22px 0}.people-metrics>div{display:grid;gap:8px;background:var(--muted);padding:22px;border-radius:10px}.people-metrics span{font-size:11px;color:var(--muted-foreground)}.people-metrics strong{font-size:28px;color:#4069ad}.people-metrics small{font-size:11px;color:var(--muted-foreground)}.district-scroll{max-height:460px;overflow:auto;margin-top:15px}.district-row{display:flex;justify-content:space-between;align-items:center;gap:15px;text-align:left;width:100%;font-size:11px;padding:12px 4px;border-bottom:1px solid var(--border);color:var(--muted-foreground)}.district-row small{display:block;font-size:11px;color:var(--muted-foreground)}.district-row b{color:#466c9e}.np-notice+.np-card{margin-top:20px}@media(max-width:850px){.finance-region-grid{grid-template-columns:1fr}.people-metrics{grid-template-columns:1fr}}</style>
